INSERT INTO `quiz_question` VALUES (1,2,1,'Sino ang pangunahing tauhan sa kuwento?'),(2,2,2,'Ano ang ipinakita ng bata?'),(3,2,3,'Ano ang ginawa ng bata?'),(4,2,4,'Ano ang magandang aral sa kuwento?'),(5,2,5,'Bakit mahalagang tumulong sa kapwa?'),(6,5,1,'What is the name of Billy\'s brother?'),(7,5,2,'His brother is how many years old?'),(8,5,3,'Which sport does he love to play?'),(9,5,4,'Who helps him in his studies?'),(10,5,5,'Billy and Thomas are _____?'),(11,6,1,'Who rides and rides the jeep?'),(12,6,2,'What is the color of the jeep?'),(13,6,3,'What is the little boy riding?'),(14,6,4,'Who loves to ride the jeep?'),(15,6,5,'How many is in the jeep?'),(16,7,1,'What is the name of the boy?'),(17,7,2,'How many years old is the boy?'),(18,7,3,'Where does the boy live?'),(19,7,4,'What is his younger brother\'s name?'),(20,7,5,'How many years old is his younger brother?'),(21,8,1,'Isang masustansyang inumin ang _____?'),(22,8,2,'Ano ang taglay ng gatas na kailangan ng tao?'),(23,8,3,'Ano ang meron sa gatas na tumutulong sa paglaki?'),(24,8,4,'Para saan ang protina na matatagpuan sa gatas?'),(25,8,5,'Saan mayaman ang gatas bukod sa protina, asukal, at taba?'),(26,9,1,'What is the title of the story?'),(27,9,2,'What do plants need in order to live and grow?'),(28,9,3,'What did Miss Cruz say about John\'s answer?'),(29,9,4,'Why do green plants need sunlight?'),(30,9,5,'What is likely to happen with green plants if there is no sunlight?'),(31,10,1,'Who rides and rides the jeep?'),(32,10,2,'What is the color of the jeep?'),(33,10,3,'What is the little boy riding?'),(34,10,4,'Who loves to ride the jeep?'),(35,10,5,'How many is in the jeep?');
