INSERT INTO `reading_material` VALUES (3,1,'Ang Batang Matulungin','A Filipino story about a helpful child','Filipino','CRLA','Grade 2','Easy','sample_filipino.jpg','sample_filipino.jpg','Ang batang matulungin ay laging handang tumulong sa kanyang mga kaibigan at pamilya. Siya ay mabait at mapagmahal sa kapwa.',25,'2026-07-25 21:31:05','Active',NULL),(38,1,'Recess Time','','English','CRLA','Grade 2','Hard','783654945_1374876501293518_6769868528839857756_n.jpg','1787892956_783654945_1374876501293518_6769868528839857756_n.jpg','Clang! Clang! It was the bell for recess. The children lined up. Some went out to play. Others went to the toilet. There were those who went to the school canteen to buy something to eat.\n\n\"I will buy a banana,\" Edna said.\n\"I will buy a chocolate,\" Norma said.\nAnita looked at her money and said.\n\" I will buy a sandwich.\"',63,'2026-08-28 12:55:57','Active',NULL),(41,1,'My Little Brother','Love our little brother.','English','Practice','Grade 3','Average','782056006_1648077403403568_6514425411348829300_n.jpg','1788185084_782056006_1648077403403568_6514425411348829300_n.jpg','I am Billy. He is my younger brother. His name is Thomas. He is 5 years old. He loves playing football. I help him with his studies. He is very cute and I love him.',35,'2026-08-31 22:04:45','Active',NULL),(43,1,'The Boy and His Jeep','The boy and his jeep.','English','Custom','Grade 3','Average','782276378_1751611246070626_5586821839370576848_n.jpg','1788893959_782276378_1751611246070626_5586821839370576848_n.jpg','This little boy is in a jeep. His jeep is green. The little boy loves his jeep. He rides and rides.',21,'2026-09-09 02:59:20','Active',NULL),(46,1,'I am Emma','Introducing Emma.','English','Custom','Grade 2','Easy','781867291_1829861501773825_439101048492603392_n.jpg','1789059589_781867291_1829861501773825_439101048492603392_n.jpg','Hello, | am Emma. | am 7 years old. | live in Canada. My hobbies are singing and dancing. | like painting, too.',18,'2026-09-11 00:59:50','Active',NULL),(47,1,'My Name is Johnny','Introducing Johnny.','English','Custom','Grade 2','Easy','777591478_1048493778007029_8250406477967388276_n.jpg','1789061890_777591478_1048493778007029_8250406477967388276_n.jpg','My name is Johnny. I am 9 years old. I live in London. I have a younger brother. His name is Jim. Jim is 5 years old.',27,'2026-09-11 01:38:11','',NULL),(50,17,'Gatas: Isang Masustansyang Inumin','Isang masustansyang inumin ang gatas.','Filipino','Custom','Grade 2','Average','Gatas.jpg','1790009540_Gatas.jpg','Taglay ng gatas ang halos lahat ng sustansyang kailangan ng tao. Ito ay may asukal at taba na nagbibigay ng init at lakas. May protina rin ito na tumutulong para tayo ay lumaki. Mayaman din ang gatas sa mineral na kailangan ng buto at ngipin. May bitamina pa para sa maayos na katawan.',53,'2026-09-22 00:52:22','',NULL),(51,17,'Air and Sunlight','Discussion in science class about air and sunlight.','English','Custom','Grade 3','Average','Gemini_Generated_Image_iymrb0iymrb0iymr.jpg','1790011513_Gemini_Generated_Image_iymrb0iymrb0iymr.jpg','Miss Cruz asked her Science class, \"What do plants need in order to live and grow?\" John answered, \"Air and sunlight.\" \"Good answer,\" said Miss Cruz. \"Green plants need sunlight to make their food. They also need water and air.\"',40,'2026-09-22 01:25:14','',NULL),(52,17,'My Name is Johnny','','English','Custom','Grade 2','Average','777591478_1048493778007029_8250406477967388276_n.jpg','1790253631_777591478_1048493778007029_8250406477967388276_n.jpg','My name is Johnny. I am 9 years old. I live in London. I have a younger brother. His name is Jim. Jim is 5 years old.',27,'2026-09-24 20:40:31','',NULL);
